shed_at":"2024-10-14"},
  {"footprint_id":"fp-0012","anonymized_handle":"A first-year Business student, Spring 2020","era_tag":"2020-2024","major":"Business Administration","first_gen_status":"continuing-generation","anonymized_demographic_band":"remote-onset cohort, mid-Atlantic suburban background","chapters":[{"title":"Week 1","prose":"My first semester was on Zoom from my parents' dining room. I'd picked Business because it felt safe. By week three I realized I had no idea what 'Business' meant.","week_range":"1-3","clr_tags":["career-exploration","self-direction"],"inflection_flag":false},{"title":"Week 6: the wall","prose":"I bombed a group case competition because I couldn't make myself speak up on a Zoom grid of nine faces. The professor's feedback was kind and devastating: 'You clearly understood the case. Why didn't anyone hear that?'","week_range":"5-7","clr_tags":["professional-communication","self-efficacy"],"inflection_flag":true},{"title":"Spring recovery","prose":"I joined a student org specifically because it met in person when things reopened. I forced myself to facilitate one meeting a month. By April, facilitating felt like a skill, not an ordeal.","week_range":"16-28","clr_tags":["professional-communication","leadership"],"inflection_flag":false},{"title":"First co-op","prose":"I co-op'd at a mid-sized consulting firm. The reason I got the offer, my manager later told me, was that I'd talked openly about the case competition I'd lost. That was the version of me they wanted in the room.","week_range":"weeks 60-72","clr_tags":["co-op-readiness","professional-narrative"],"inflection_flag":false}],"skill_trajectory":[{"competency":"professional-communication","t0_score":2.3,"t8_score":2,"t16_score":3.8},{"competency":"self-efficacy","t0_score":2.6,"t8_score":2.1,"t16_score":3.9}],"escalation_status":"open","escalation_capacity_per_month":1,"k_anonymity_score":6,"ferpa_audit_id":"log-20241018-0044","published_at":"2024-10-18"},
