      try {
        const sysPrompt = "Generate a highly specific, 2-sentence metacognitive reflection prompt based on the footprint the student just read. Output strictly as JSON.";
        const userPrompt = `Footprint read: fp-0007. Generate prompt.`;
        const res = await callAIWithVS(sysPrompt, userPrompt);
        const parsed = JSON.parse(res.text.replace(/```json|```/g, ''));
        setPrompt(parsed.prompt_text || "What is one thing you will take away from this footprint?");
