const JourneyReader = ({ navigate, context }) => {
  const { quietMode } = useContext(AppContext);
  const [narrative, setNarrative] = useState(null);
  const [loading, setLoading] = useState(true);
  const [showInflection, setShowInflection] = useState(false);
  const [showSparkline, setShowSparkline] = useState(false);
  const [scrollProgress, setScrollProgress] = useState(0);

  const footprintId = context?.footprintId || 'fp-0007';
  const fpData = SEED_ALUMNI_FOOTPRINTS.find(f => f.footprint_id === footprintId) || SEED_ALUMNI_FOOTPRINTS[0];

  useEffect(() => {
    const fetchNarrative = async () => {
      setLoading(true);
      try {
        const sysPrompt = "You are an empathetic editorial writer (New Yorker style). Transform raw CLR competency scores and timeline events into a 4-chapter narrative. Maintain k-anonymity. Do not use real names or employers. Output strictly as JSON.";
        const userPrompt = `Synthesize narrative for footprint ${footprintId} using CLR data: ${JSON.stringify(fpData.chapters)}`;

        // Using VS for creative narrative synthesis
        const res = await callAIWithVS(sysPrompt, userPrompt);
        let parsed;
        try {
          parsed = JSON.parse(res.text.replace(/```json|```/g, ''));
        } catch(e) {
          // Fallback to seed data if AI fails to return valid JSON
          parsed = { chapters: fpData.chapters.map(c => ({ ...c, isInflection: c.inflection_flag, sparklineData: [{week:6, score:2.1}, {week:8, score:1.8}, {week:10, score:2.5}, {week:12, score:3.0}, {week:14, score:3.4}] })) };
        }
        setNarrative(parsed);
      } catch (err) {
        console.error(err);
        // Fallback to seed data
        setNarrative({ chapters: fpData.chapters.map(c => ({ ...c, isInflection: c.inflection_flag, sparklineData: [{week:6, score:2.1}, {week:8, score:1.8}, {week:10, score:2.5}, {week:12, score:3.0}, {week:14, score:3.4}] })) });
      } finally {
        setLoading(false);
      }
    };
    fetchNarrative();
  }, [footprintId]);

  useEffect(() => {
    const handleScroll = () => {
      const totalScroll = document.documentElement.scrollTop;
      const windowHeight = document.documentElement.scrollHeight - document.documentElement.clientHeight;
      const scroll = `${totalScroll / windowHeight}`;
      setScrollProgress(scroll);

      // Simple intersection logic for prototype
      const inflectionEl = document.getElementById('inflection-chapter');
      if (inflectionEl) {
        const rect = inflectionEl.getBoundingClientRect();
        if (rect.top < window.innerHeight * 0.75 && !showInflection) {
          setShowInflection(true);
          // In a real app, we'd fire ai_inflection_detection here. 
          // For prototype, we simulate the fetch resolving instantly since we pre-loaded sparklineData in the fallback.
        }
      }
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, [showInflection]);

  if (loading) {
