const App = () => {
  const [currentScreen, setCurrentScreen] = useState('library_home');
  const [quietMode, setQuietMode] = useState(false);
  const [contextData, setContextData] = useState({});
  const [toast, setToast] = useState(null);

  const navigate = (screen, data = {}) => {
    setContextData(data);
    setCurrentScreen(screen);
    window.scrollTo(0, 0);
  };

  const showToast = (message, variant = 'success') => {
    setToast({ message, variant });
  };

  useEffect(() => {
    // Inject CSS variables
    const style = document.createElement('style');
    style.innerHTML = `
      @import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Mono&family=Open+Sans:ital,wght@0,400;0,600;0,700;1,400&family=Roboto+Condensed:wght@700&display=swap');
      :root {
        --color-background: #FFFFFF;
        --color-surface: #F7F7F7;
        --color-panel: #F0F0F0;
        --color-text-primary: #000000;
        --color-text-secondary: #414141;
        --color-text-tertiary: #737373;
        --color-border: #D9D9D9;
        --color-emphasis: #C8102E;
        --color-success: #0F8A4B;
        --color-warning: #B5651D;
        --color-friction: #9E0A24;
        --font-display: 'Roboto Condensed', sans-serif;
        --font-body: 'Open Sans', sans-serif;
        --font-data: 'IBM Plex Mono', monospace;
      }
      * { box-sizing: border-box; }
      body { margin: 0; font-family: var(--font-body); background-color: var(--color-background); color: var(--color-text-primary); }
    `;
    document.head.appendChild(style);
    return () => document.head.removeChild(style);
  }, []);

  const renderScreen = () => {
    switch (currentScreen) {
      case 'library_home': return <LibraryHome navigate={navigate} />;
      case 'search_results': return <SearchResults navigate={navigate} context={contextData} />;
      case 'journey_reader': return <JourneyReader navigate={navigate} context={contextData} />;
      case 'reflection_journal': return <ReflectionJournal navigate={navigate} context={contextData} />;
      case 'unmask_connect': return <UnmaskConnect navigate={navigate} context={contextData} />;
      case 'liz_dashboard': return <LizDashboard />;
      default: return <LibraryHome navigate={navigate} />;
    }
  };

  return (
    <AppContext.Provider value={{ quietMode, toggleQuietMode: () => setQuietMode(!quietMode), showToast }}>
      <div style={{ position: 'relative', minHeight: '100vh' }}>
        {/* Demo Controls */}
        <div style={{ position: 'fixed', top: 8, right: 8, zIndex: 9999, display: 'flex', gap: '8px' }}>
          <select 
            value={currentScreen} 
            onChange={(e) => navigate(e.target.value)}
            style={{ padding: '4px 8px', fontSize: '12px', borderRadius: '4px', border: '1px solid #CCC' }}
          >
            <option value="library_home">Library Home</option>
            <option value="search_results">Search Results</option>
            <option value="journey_reader">Journey Reader</option>
            <option value="reflection_journal">Reflection Journal</option>
            <option value="unmask_connect">Unmask & Connect</option>
            <option value="liz_dashboard">Liz's Dashboard</option>
          </select>
        </div>

        <AnimatePresence mode="wait">
          <motion.div
            key={currentScreen}
            initial={{ opacity: 0, x: 10 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -10 }}
            transition={{ duration: quietMode ? 0.4 : 0.2 }}
          >
            {renderScreen()}
          </motion.div>
        </AnimatePresence>

        <AnimatePresence>
          {toast && <Toast message={toast.message} variant={toast.variant} onClose={() => setToast(null)} />}
        </AnimatePresence>
      </div>
    </AppContext.Provider>
  );
};

function __test_state_transitions__() {
  console.assert(typeof App === 'function', 'App must be a component');
  return true;
}
if (typeof window !== 'undefined') {
  window.__hicProtoTests = __test_state_transitions__;
}
